import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import com.sun.source.tree.*;import com.sun.source.util.*;
public class NativeConstructorScanner {
 public static void main(String[] a)throws Exception{JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);JavacTask t=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(a[1]))).trim(),"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(a[0]))));Trees tr=Trees.instance(t);List<CompilationUnitTree>us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);t.analyze();for(CompilationUnitTree u:us)new TreePathScanner<Void,Void>(){public Void visitNewClass(NewClassTree n,Void v){Element e=tr.getElement(getCurrentPath());if(e instanceof ExecutableElement&&e.getEnclosingElement().toString().equals("net.minecraft.util.math.AxisAlignedBB")&&((ExecutableElement)e).getParameters().size()==6){boolean valid=true;for(VariableElement p:((ExecutableElement)e).getParameters())valid&=p.asType().toString().equals("double");if(valid)System.out.println(Paths.get(u.getSourceFile().toUri())+"\t"+tr.getSourcePositions().getStartPosition(u,n)+"\t"+tr.getSourcePositions().getEndPosition(u,n)+"\t(DDDDDD)V");}return super.visitNewClass(n,v);}}.scan(u,null);System.err.println("Attribution only, unfinished-port errors: "+d.getDiagnostics().stream().filter(x->x.getKind()==Diagnostic.Kind.ERROR).count());}}
